import { RealEstateConfig } from './template-configs';

export function getCanonicalBdsConfig(slugOrCode?: string): RealEstateConfig | null {
  if (!slugOrCode) return null;
  const raw = slugOrCode.toLowerCase().trim();
  const clean = raw.replace(/^template-/, '');

  if (BDS_CANONICAL_CONFIGS[clean]) {
    return BDS_CANONICAL_CONFIGS[clean];
  }

  const lpMatch = clean.match(/(?:lp|landing)[-_#\s]*0?([1-7])\b/i);
  if (lpMatch) {
    const key = `lp-${lpMatch[1].padStart(2, '0')}`;
    if (BDS_CANONICAL_CONFIGS[key]) return BDS_CANONICAL_CONFIGS[key];
  }

  const bdsMatch = clean.match(/(?:bds|template|portal)[-_#\s]*0?([1-9]|1[0-9]|2[0-4])\b/i);
  if (bdsMatch) {
    const key = `bds-${bdsMatch[1].padStart(2, '0')}`;
    if (BDS_CANONICAL_CONFIGS[key]) return BDS_CANONICAL_CONFIGS[key];
  }

  return BDS_CANONICAL_CONFIGS['bds-01'] || null;
}

