            "slug": "dia-oc-da-nang-trong-nhung-nam-gan-day",
            "summary": "Tại các dự án nhà ở thương mại và đất nền pháp lý chuẩn tại Đà Nẵng, lượng giao dịch đang tăng trưởng ấn tượng nhờ chính sách kích cầu hạ tầng...",
